mapper.select:
SELECT * FROM (
    SELECT R.REQ_ID, R.LOGIN_ID, R.USER_NAME, R.DEPT_NAME, R.KIND, R.START_DATE, R.END_DATE, R.HALF_DAY,
           R.START_TIME, R.END_TIME, R.DAYS, R.HOURS, R.DESTINATION, R.REASON, R.DOC_ID, R.CREATED_AT,
           R.TRIP_AREA, R.TRIP_HOURS, R.OFFICIAL_CAR, R.LODGING_NIGHTS, R.LODGING_REGION, R.EST_AMOUNT,
           D.STATUS AS DOC_STATUS
      FROM DUTY_REQUEST R JOIN APPROVAL_DOC D ON D.DOC_ID = R.DOC_ID
     WHERE R.LOGIN_ID = #{loginId} AND D.DELETED_YN = 'N'
       AND EXTRACT(YEAR FROM R.START_DATE) = #{year}
     ORDER BY R.START_DATE DESC, R.REQ_ID DESC
) WHERE ROWNUM <= #{limit}

SELECT NVL(SUM(R.DAYS), 0) FROM DUTY_REQUEST R JOIN APPROVAL_DOC D ON D.DOC_ID = R.DOC_ID
 WHERE R.LOGIN_ID = #{loginId} AND R.KIND = #{kind} AND EXTRACT(YEAR FROM R.START_DATE) = #{year}
   AND D.STATUS = #{status} AND D.DELETED_YN = 'N'
